{
  "name": "Infisical 2.0",
  "version": 1,
  "meta": {
    "source": "Infisical 2.0 design system"
  },
  "color": {
    "note": "Neutral first. Ink on warm off-white, one accent (Infisical neon lime in both themes), status colors that always travel with a word or icon. The app is a sidebar beside an inset, both light in light and both dark in dark. Dark mirrors light: ink becomes bone, the accent takes over the on switch and the mark, and selection stays neutral.",
    "themes": [
      {
        "id": "light",
        "name": "Light"
      },
      {
        "id": "dark",
        "name": "Dark"
      }
    ],
    "tokens": [
      {
        "name": "frame",
        "value": {
          "light": "#010101",
          "dark": "#010101"
        },
        "usage": "Near-black ground. The dark-theme sidebar sits on it (through sidebar); in light the sidebar is light and nothing in the app shell uses frame. It never wraps the inset. Never put text on it except inside the sidebar."
      },
      {
        "name": "frame-soft",
        "value": {
          "light": "#ecebe5",
          "dark": "#010101"
        },
        "usage": "Warm ground for embedded views and docs that want a frame around their content. In dark it matches frame."
      },
      {
        "name": "surface",
        "value": {
          "light": "#fbfbf9",
          "dark": "#0b0b0b"
        },
        "usage": "The main panel and every inset card and input. Menus, popovers and dialogs float on pop. The default ground for text."
      },
      {
        "name": "pop",
        "value": {
          "light": "#ffffff",
          "dark": "#161616"
        },
        "usage": "Ground of everything that floats above the page: menus, listboxes, popovers, hover cards, dialogs, sheets and drawers. A step lighter than surface in both themes (1.04:1 in light, 1.09:1 in dark), so a panel reads as raised even where its shadow is lost on a dark page. Ink is 20.9:1 on it in light and 15.9:1 in dark; muted is 7.4:1 and 8.3:1. Always with pop-line and shadow-pop."
      },
      {
        "name": "pop-line",
        "value": {
          "light": "{line-soft}",
          "dark": "{line}"
        },
        "usage": "The 1px edge of a pop panel, drawn as a ring inside its shadow so separators and rows keep a whole-pixel 4px inset."
      },
      {
        "name": "inset",
        "value": {
          "light": "{surface}",
          "dark": "{surface}"
        },
        "usage": "The app's main content area beside the sidebar. It sits straight on the page with no frame, and pads space-40 (bottom space-48). Always surface, so cards and tables read the same inside it."
      },
      {
        "name": "sidebar",
        "value": {
          "light": "{tint}",
          "dark": "{frame}"
        },
        "usage": "Ground of the app sidebar. tint in light (1.1:1 against the inset, so it needs sidebar-line) and frame in dark. Text on it uses ink, text2 and muted: muted is 6.4:1 in light and 9.6:1 in dark. The current page is sidebar-current with ink text; counts are accent Counts, and a rail dot, which has no number, is accent-fg."
      },
      {
        "name": "sidebar-line",
        "value": {
          "light": "{line}",
          "dark": "{line-soft}"
        },
        "usage": "The 1px rule between the sidebar and the inset, and separators inside the sidebar."
      },
      {
        "name": "sidebar-hover",
        "value": {
          "light": "{line-soft}",
          "dark": "{tint}"
        },
        "usage": "Hover ground of nav rows and buttons in the sidebar. A step darker than the light sidebar (tint alone would vanish on it), a step lighter than the dark one."
      },
      {
        "name": "sidebar-current",
        "value": {
          "light": "#d9d8d3",
          "dark": "#2c2c2b"
        },
        "usage": "The current page in the sidebar, and a rail group that holds it: ink at the press step over the sidebar (10% over tint in light, 18% over frame in dark), a step past sidebar-hover (1.25:1 against the light sidebar where hover is 1.10:1; 1.49:1 in dark where hover is 1.22:1). Ink text on it at 600 is 14.6:1 in light and 12.2:1 in dark. Neutral, like every selection; in the sidebar only counts take the accent."
      },
      {
        "name": "paper",
        "value": {
          "light": "#f4f3ee",
          "dark": "#121212"
        },
        "usage": "Dialog and sheet footers. A step off surface so the action bar reads as a shelf."
      },
      {
        "name": "tint",
        "value": {
          "light": "#f1f0ea",
          "dark": "#1c1c1c"
        },
        "usage": "Borderless shells around inset surfaces (cards, tables, lists), table headers, segmented tracks, disabled and read-only fields, the hover ground of striped table rows, and the light sidebar (through sidebar). In dark it is lifted so a borderless shell still reads against surface (1.15:1)."
      },
      {
        "name": "row-done",
        "value": {
          "light": "#f6f5f1",
          "dark": "#101010"
        },
        "usage": "Resolved list items that stay in place so nothing jumps."
      },
      {
        "name": "select",
        "value": {
          "light": "#eeede6",
          "dark": "#262626"
        },
        "usage": "Selection in connected rows: a list's current and checked rows, selected table and tree rows, DataGrid ranges, the pressed toggle Button. On rows it is the whole signal, with the row text one step up (text2 to ink, muted to text2); no edge bar. Neutral in both themes, never tinted: in dark it is 1.30:1 on surface and a step above tint (1.13:1), the same step as before."
      },
      {
        "name": "line-soft",
        "value": {
          "light": "#e6e5e0",
          "dark": "#1e2022"
        },
        "usage": "Hairlines between rows inside a surface, skeleton blocks, progress tracks, soft badges."
      },
      {
        "name": "line",
        "value": {
          "light": "#d8d8d4",
          "dark": "#2f3234"
        },
        "usage": "Borders of inset surfaces, plain cards, compact lists, popovers and dialogs; section rules. Shells around inset surfaces have no border."
      },
      {
        "name": "control",
        "value": {
          "light": "#b0b0a9",
          "dark": "#3f4245"
        },
        "usage": "Borders of inputs, selects and secondary buttons. Source pair: 2.1:1 on surface in light and 2.0:1 in dark, below the 3:1 floor for control borders. Kept exact; focus turns the border ink with a 3px nudge outline. An invalid field rests on bad-control and turns bad with the 3px bad outline while focused."
      },
      {
        "name": "faint",
        "value": {
          "light": "#8e9291",
          "dark": "#8e9291"
        },
        "usage": "Disabled text and separators like the breadcrumb slash only. 3.0:1 on surface in light (6.3:1 in dark): never for text people must read."
      },
      {
        "name": "muted",
        "value": {
          "light": "#565654",
          "dark": "#b0b0a9"
        },
        "usage": "Secondary text, descriptions, placeholders, eyebrows and captions. 7.1:1 on surface, 6.4:1 on tint in light; 9.0:1 and 7.8:1 in dark."
      },
      {
        "name": "text2",
        "value": {
          "light": "#2f3234",
          "dark": "#d8d8d4"
        },
        "usage": "Body copy that sits one step below ink: descriptions in alerts, table cells, ghost button labels. 12.5:1 on surface in light, 13.8:1 in dark."
      },
      {
        "name": "ink",
        "value": {
          "light": "#010101",
          "dark": "#f1f0ea"
        },
        "usage": "Primary text and icons on surface, tint, paper and select (at least 17:1 in light, 13:1 in dark). Also the fill of checked controls and person avatars."
      },
      {
        "name": "on-ink",
        "value": {
          "light": "#ffffff",
          "dark": "#010101"
        },
        "usage": "Text and icons on an ink fill: checked checkboxes, person avatars, tooltips."
      },
      {
        "name": "accent",
        "value": {
          "light": "#e3ef59",
          "dark": "#e7f256"
        },
        "usage": "The one accent. Counts (in the sidebar and the bulk action bar), the on switch track, the slider range and thumb, approval buttons and search highlights; the current page in the sidebar stays neutral. Infisical neon lime in both themes: #e3ef59 in light, #e7f256 in dark. On light grounds the fill is nearly as light as the ground (1.10:1 on the sidebar, 1.21:1 on surface) and carries no edge: it is a highlight, and what it says is its on-accent text (16.7:1 on it), so the label, not the fill, identifies the control or the number. Never let a bare fill with no text carry meaning (a dot, a bar); use accent-fg for those. In dark it stands out on its own (17:1 on the sidebar). A fill, never text on light grounds. For accent-colored text and icons (toast actions, the banner), use accent-fg."
      },
      {
        "name": "accent-2",
        "value": {
          "light": "#d3de42",
          "dark": "#d5e03a"
        },
        "usage": "Hover and pressed fill of accent buttons. A step darker than accent on the same hue; on-accent on it is 14.2:1 in light."
      },
      {
        "name": "on-accent",
        "value": {
          "light": "#010101",
          "dark": "#010101"
        },
        "usage": "Text and icons on an accent fill (16.7:1 in light, 17:1 in dark; 14.2:1 on accent-2 in light)."
      },
      {
        "name": "accent-wash",
        "value": {
          "light": "#f7facc",
          "dark": "#1c1e10"
        },
        "usage": "Very light accent ground for a highlighted row, a callout and the production banner. Text on it is ink (19.4:1 light, 14.8:1 dark)."
      },
      {
        "name": "accent-line",
        "value": {
          "light": "#dddd8e",
          "dark": "#3d4220"
        },
        "usage": "Border of the production banner and other accent-wash callouts. A step darker than the wash (1.32:1 against it in light), like the status -line colors."
      },
